var l=[{title:`Τύποι στήριξης`,text:`Οι μπάρες μοχλού για κάσα πόρτας, οι εκτεινόμενες μπάρες τάσης, οι σταθερές μπάρες τοίχου και οι μπάρες οροφής εγκαθίστανται διαφορετικά. Μια μπάρα που πωλείται ως «συμβατή με πόρτες» δεν θα ταιριάζει σε κάθε πλαίσιο, τοίχο ή κάσα. Ορισμένοι τύποι χρειάζονται δομικά στηρίγματα σε συμπαγείς υποστηρίξεις, και άλλοι εξαρτώνται από συγκεκριμένο σχήμα πλαισίου.`},{title:`Ελέγξτε το όριο και τη δομή`,text:`Διαβάστε τις οδηγίες του κατασκευαστή και το όριο βάρους, συμπεριλαμβανομένου αν επιτρέπονται οι δυναμικές κινήσεις. Υπολογίστε ολόκληρο το σωματικό σας βάρος συν την επιπλέον δύναμη της αιώρησης ή του τραβήγματος. Επιθεωρήστε τις βίδες, τους βραχίονες, την επένδυση και τις επιφάνειες που αγγίζει ή πλησιάζει η μπάρα. Αν δεν είστε σίγουροι για τη δομή του κτιρίου ή τη μέθοδο στήριξης, ρωτήστε έναν ειδικευμένο τεχνικό εγκατάστασης.`},{title:`Δοκιμάστε την βήμα βήμα`,text:`Πριν από ένα πλήρες κρέμασμα, βεβαιωθείτε ότι η μπάρα έχει εδραστεί σωστά και δεν μπορεί να περιστραφεί, να γλιστρήσει ή να μετατοπιστεί. Κρατήστε τα πόδια σας στο πάτωμα και πιέστε την ήπια και με έλεγχο. Περάστε σε ένα μερικό κρέμασμα και μετά σε ένα πλήρες κρέμασμα με στήριξη μόνο όταν ξέρετε ότι η εγκατάσταση είναι στέρεη. Μια σύντομη δοκιμή δεν μπορεί να αποδείξει ότι ο φθαρμένος εξοπλισμός ή ένα ακατάλληλο πλαίσιο είναι ασφαλή.`},{title:`Συνηθισμένοι κίνδυνοι`,text:`Μην προσαρτάτε λάστιχα και μην κάνετε kipping, αιωρήσεις ή pull-ups με βάρος, εκτός αν το προϊόν έχει σχεδιαστεί και εγκατασταθεί ακριβώς για αυτό. Αφήστε χώρο για το κεφάλι, τους αγκώνες και τα πόδια σας, χωρίς γυαλί ή αιχμηρά έπιπλα κοντά. Σταματήστε να χρησιμοποιείτε μια μπάρα που τρίζει, γλιστρά, λυγίζει ή χαλαρώνει.`},{title:`Χρήση του TrainUp`,text:`Στο Profile, σημειώστε τη μπάρα pull-up ως ασφαλώς εγκατεστημένη μόνο αφού ελέγξετε όλα τα παραπάνω. Μέχρι τότε, το πρόγραμμά σας παραλείπει ασκήσεις που χρειάζονται τη μπάρα, και οι κωπηλασίες ή οι ασκήσεις με λάστιχο και ασφαλές σημείο αγκύρωσης προπονούν την ίδια έλξη. Αν είστε αρχάριος, τα κρεμάσματα με στήριξη, οι έλξεις ωμοπλατών ή τα pull-ups με βοήθεια είναι καλά πρώτα βήματα όταν η μπάρα είναι ασφαλής.`}];var i=[{label:`Mayo Clinic: ασφάλεια και τεχνική στην προπόνηση με βάρη`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`},{label:`Βιβλιοθήκη ασκήσεων του ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Θέση του ACSM για το 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var s={sections:l,sources:i};export{s as default,l as sections,i as sources};